        NodePointer nodePointer = mock(NodePointer.class);
        attributeContext.currentNodePointer = nodePointer;
        //Act
        NodePointer result = attributeContext.getCurrentNodePointer();
        //Assert
        assertThat(result, is(nodePointer));
    }

